{
  "findings": [
    {
      "check_id": "CKV2_AWS_73",
      "title": "Ensure AWS SQS uses CMK not AWS default keys for encryption",
      "resource": "aws_sqs_queue.pass2",
      "severity": "MEDIUM",
      "explanation": "The SQS queue is using AWS-managed keys for encryption instead of a customer-managed key (CMK). Using CMKs provides better control over encryption and key management."
    }
  ],
  "patched_code": "resource \"aws_sqs_queue\" \"pass2\" {\n  name                    = \"unencrypted-queue\"\n  kms_master_key_id       = \"arn:aws:kms:region:account-id:key/key-id\"\n}\n",
  "fix_summary": "Replaced AWS-managed encryption with a customer-managed key (CMK) for the SQS queue to enhance encryption control and security."
}
